INSERT INTO `products` (`id`, `category_id`, `name`, `model_number`, `apn_number`, `slug`, `short_description`, `full_description`, `translations`, `main_image`, `gallery`, `pdf_datasheet`, `pdf_manual`, `pdf_brochure`, `pdf_service_manual`, `price`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 3, 'Ultra-Microbalance AXR 2UA', 'AXR 2UA', NULL, 'aczet-axr-2ua', 'Next-generation ultra microbalance designed for extremely precise weighing of ultra-light samples. With 2.1 g capacity and 0.1 µg readability, the AXR 2UA delivers exceptional accuracy for advanced laboratory applications. It features a colour TFT touchscreen, automatic motorised internal calibration with PSAC, and a user-friendly interface for reliable, secure, and efficient micro-weighing performance.', 'Precision Aczet AXR 2UA Ultra Microbalances offering 2.1 g weighing capacity and 0.1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-2ua-datasheet.pdf', 'docs/aczet-axr-2ua-user-manual.pdf', NULL, 'docs/aczet-axr-2ua-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(2, 3, 'Microbalance AXR 2MA', 'AXR 2MA', NULL, 'aczet-axr-2ma', 'Next-generation weighing technology with a solid, durable construction for long-term reliability. High-precision performance with 2.1 g capacity and 1 µg readability for accurate micro-weighing. Intuitive color TFT touchscreen display with internal calibration and easy leveling alerts. Supports 21 CFR part 11 compliant user management for secure and regulated laboratory operations. Multiple connectivity options including USB, RS232, and Ethernet for seamless data integration. Compact design with overload protection and power-saving mode, ideal for modern laboratories.', 'Precision Aczet AXR 2MA Microbalances offering 2.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-2ma-datasheet.pdf', 'docs/aczet-axr-2ma-user-manual.pdf', NULL, 'docs/aczet-axr-2ma-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(3, 3, 'Microbalance AXR 6MA', 'AXR 6MA', NULL, 'aczet-axr-6ma', 'Next-generation weighing technology with a solid, durable construction for long-term reliability. High-precision performance with 2.1 g capacity and 1 µg readability for accurate micro-weighing. Intuitive color TFT touchscreen display with internal calibration and easy leveling alerts. Supports 21 CFR Part 11 compliant user management for secure and regulated laboratory operations. Multiple connectivity options including USB, RS232, and Ethernet for seamless data integration. Compact design with overload protection and power-saving mode, ideal for modern laboratories.', 'Precision Aczet AXR 6MA Microbalances offering 6.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-6ma-datasheet.pdf', 'docs/aczet-axr-6ma-user-manual.pdf', NULL, 'docs/aczet-axr-6ma-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(4, 3, 'Microbalance AXR 11MA', 'AXR 11MA', NULL, 'aczet-axr-11ma', 'Next-generation weighing technology with a solid, durable construction for long-term reliability. High-precision performance with 2.1 g capacity and 1 µg readability for accurate micro-weighing. Intuitive color TFT touchscreen display with internal calibration and easy leveling alerts. Supports 21 CFR Part 11 compliant user management for secure and regulated laboratory operations. Multiple connectivity options including USB, RS232, and Ethernet for seamless data integration. Compact design with overload protection and power-saving mode, ideal for modern laboratories.', 'Precision Aczet AXR 11MA Microbalances offering 11.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-11ma-datasheet.pdf', 'docs/aczet-axr-11ma-user-manual.pdf', NULL, 'docs/aczet-axr-11ma-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(5, 3, 'Microbalance Filter AXR 2MF', 'AXR 2MF', NULL, 'aczet-axr-2mf', 'Advanced weighing technology with a solid, robust construction designed for filter microbalance applications. High-accuracy performance with 2.1 g capacity and 1 µg readability for ultra-precise measurements. Ideal for filter weighing in environmental monitoring, air quality analysis, and particulate matter (PM) testing. User-friendly color TFT touchscreen with internal calibration and easy leveling alerts for consistent results. Secure 21 CFR Part 11 compliant user management with USB, RS232, and Ethernet connectivity. Compact footprint with overload protection and power-saving mode, optimized for daily laboratory workflows.', 'Precision Aczet AXR 2MF Filter Microbalances offering 2.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-2mf-datasheet.pdf', 'docs/aczet-axr-2mf-user-manual.pdf', NULL, 'docs/aczet-axr-2mf-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(6, 3, 'Microbalance Filter AXR 5MF', 'AXR 5MF', NULL, 'aczet-axr-5mf', 'Advanced weighing technology with a solid, robust construction designed for filter microbalance applications. High-accuracy performance with 2.1 g capacity and 1 µg readability for ultra-precise measurements. Ideal for filter weighing in environmental monitoring, air quality analysis, and particulate matter (PM) testing. User-friendly color TFT touchscreen with internal calibration and easy leveling alerts for consistent results. Secure 21 CFR Part 11 compliant user management with USB, RS232, and Ethernet connectivity. Compact footprint with overload protection and power-saving mode, optimized for daily laboratory workflows.', 'Precision Aczet AXR 5MF Filter Microbalances offering 5.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-5mf-datasheet.pdf', 'docs/aczet-axr-5mf-user-manual.pdf', NULL, 'docs/aczet-axr-5mf-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(7, 3, 'Microbalance Filter AXR 6MF', 'AXR 6MF', NULL, 'aczet-axr-6mf', 'Advanced weighing technology with a solid, robust construction designed for filter microbalance applications. High-accuracy performance with 2.1 g capacity and 1 µg readability for ultra-precise measurements. Ideal for filter weighing in environmental monitoring, air quality analysis, and particulate matter (PM) testing. User-friendly color TFT touchscreen with internal calibration and easy leveling alerts for consistent results. Secure 21 CFR Part 11 compliant user management with USB, RS232, and Ethernet connectivity. Compact footprint with overload protection and power-saving mode, optimized for daily laboratory workflows.', 'Precision Aczet AXR 6MF Filter Microbalances offering 6.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-6mf-datasheet.pdf', 'docs/aczet-axr-6mf-user-manual.pdf', NULL, 'docs/aczet-axr-6mf-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(8, 3, 'Microbalance Filter AXR 11MP', 'AXR 11MP', NULL, 'aczet-axr-11mp', 'Advanced weighing technology with a solid, robust construction designed for precision microbalance applications. High-accuracy performance with 11.1 g capacity and 1 µg readability for ultra-precise gravimetric measurements. Ideal for pipette calibration and gravimetric testing in accordance with ISO 8655 standards. User-friendly color TFT touchscreen display with internal calibration and easy leveling alerts for reliable results. Supports 21 CFR Part 11 compliant user management with USB, RS232, and Ethernet connectivity. Compact footprint with overload protection and power-saving mode, optimized for regulated laboratory environments.', 'Precision Aczet AXR 11MP pipette Check Microbalances offering 11.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-11mp-datasheet.pdf', 'docs/aczet-axr-11mp-user-manual.pdf', NULL, 'docs/aczet-axr-11mp-service-manual.pdf', NULL, 1, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(9, 3, 'Microbalance Filter AXR 6MS', 'AXR 6MS', NULL, 'aczet-axr-6ms', 'Advanced weighing technology with a solid, robust construction designed for precision microbalance applications. High-accuracy performance with 6.1 g capacity and 1 µg readability, ideal for stent weighing in medical device manufacturing requiring ultra-precise mass determination. User-friendly color TFT touchscreen display with internal calibration and easy leveling alerts for reliable results. Supports 21 CFR Part 11–compliant user management with USB, RS232, and Ethernet connectivity. Compact footprint with overload protection and power-saving mode, optimized for regulated laboratory environments.', 'Precision Aczet AXR 6MS STENT Microbalances offering 6.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/axr-microbalance.png', '[\"images/products/cm21.svg\"]', 'docs/aczet-axr-6ms-datasheet.pdf', 'docs/aczet-axr-6ms-user-manual.pdf', NULL, 'docs/aczet-axr-6ms-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(10, 3, 'Hallmarking Microbalance CM 2', 'CM 2', NULL, 'aczet-cm-2', '', 'Precision Aczet CM 2 Microbalances offering 2 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-2-datasheet.pdf', 'docs/aczet-cm-2-user-manual.pdf', NULL, 'docs/aczet-cm-2-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(11, 3, 'Microbalance CM 5', 'CM 5', NULL, 'aczet-cm-5', 'Intuitive to operate with solid built construction; 2.1 g capacity; 1 µg readability; large, bright LCD backlit display; internal calibration; easy leveling; USB and RS232 connection; overload protection; application: accurate weighing of microgram samples for pharmaceutical, analytical, and research laboratory use.', 'Precision Aczet CM 5 Microbalances offering 5 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-5-datasheet.pdf', 'docs/aczet-cm-5-user-manual.pdf', NULL, 'docs/aczet-cm-5-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
