(15, 3, 'Microbalance CM 5F', 'CM 5F', NULL, 'aczet-cm-5f', 'High-Precision Microbalance – Solid construction, 2.1 g capacity, 1 µg readability, large backlit LCD, internal calibration, easy leveling, USB/RS232 connectivity, overload protection. Designed for environmental monitoring, filter microbalance measurements, and particulate matter (PM) analysis for pollution control.', 'Precision Aczet CM 5F Filter Microbalances offering 5 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-5f-datasheet.pdf', 'docs/aczet-cm-5f-user-manual.pdf', NULL, 'docs/aczet-cm-5f-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(16, 3, 'Microbalance CM 6F', 'CM 6F', NULL, 'aczet-cm-6f', 'High-Precision Microbalance – Solid construction, 2.1 g capacity, 1 µg readability, large backlit LCD, internal calibration, easy leveling, USB/RS232 connectivity, overload protection. Designed for environmental monitoring, filter microbalance measurements, and particulate matter (PM) analysis for pollution control.', 'Precision Aczet CM 6F Filter Microbalances offering 6.1 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-6f-datasheet.pdf', 'docs/aczet-cm-6f-user-manual.pdf', NULL, 'docs/aczet-cm-6f-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(17, 3, 'Microbalance CM 11F', 'CM 11F', NULL, 'aczet-cm-11f', 'High-Precision Microbalance – Solid construction, 2.1 g capacity, 1 µg readability, large backlit LCD, internal calibration, easy leveling, USB/RS232 connectivity, overload protection. Designed for environmental monitoring, filter microbalance measurements, and particulate matter (PM) analysis for pollution control.', 'Precision Aczet CM 11F Filter Microbalances offering 11 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-11f-datasheet.pdf', 'docs/aczet-cm-11f-user-manual.pdf', NULL, 'docs/aczet-cm-11f-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
(18, 3, 'Microbalance Pipette CM 11P', 'CM 11P', NULL, 'aczet-cm-11p', 'High-Precision Microbalance – Solid construction, 11 g capacity, 1 µg readability, large backlit LCD, internal calibration, easy leveling, USB/RS232 connectivity, overload protection. Ideal for precise pipette calibration in laboratories.', 'Precision Aczet CM 11P Pipette Check Microbalances offering 11 g weighing capacity and 1 µg readability with high accuracy for rigorous analytical workflows. Backed by ISO/IEC 17025 certified calibration and Aczet factory warranty.', NULL, 'images/products/cm21.svg', '[\"images/products/cm21.svg\"]', 'docs/aczet-cm-11p-datasheet.pdf', 'docs/aczet-cm-11p-user-manual.pdf', NULL, 'docs/aczet-cm-11p-service-manual.pdf', NULL, 0, 1, '2026-10-06 05:48:40', '2026-10-06 05:48:40'),
